module.exports = [
{ e: "🐢", art: { b: "🐢", s: ["🏖️", "🌙", "🥚", "🌊"], c: ["#0B4E3A", "#3AA08A"] },
pt: { h: "Numa noite de lua na praia, Nina e Leo viram um grupo de pessoas com lanternas vermelhas olhando a areia. De repente, filhotinhos de tartaruga começaram a sair de um buraco e correr para o mar! “Eles sabem o caminho sozinhos”, sussurrou o vovô, emocionado.", t: "As tartarugas marinhas", f: "As tartarugas marinhas vivem no mar, mas as fêmeas voltam à praia para cavar ninhos e botar ovos na areia. Os filhotes nascem à noite e correm para a água guiados pelo brilho do horizonte. Muitas fêmeas voltam, anos depois, para botar ovos na mesma região onde nasceram.", x: "A temperatura da areia decide se o filhote vai ser macho ou fêmea! Areia mais quente gera mais fêmeas, e areia mais fresca, mais machos.", s: ["Existem sete espécies de tartarugas marinhas no mundo, e cinco delas fazem ninhos no Brasil.", "O Projeto Tamar protege as tartarugas marinhas no litoral brasileiro desde 1980.", "Luzes fortes perto da praia confundem os filhotes, que podem ir para o lado errado em vez de ir para o mar."], ex: { t: "Areia quente, areia fresca", m: "dois potes com areia ou terra, um lugar ao sol, um lugar à sombra", p: ["Coloque um pote no sol e o outro na sombra por algumas horas.", "Enfie o dedo na areia de cada um, até a metade. Qual está mais quente?", "Num ninho de tartaruga, essa diferença decide quantos filhotes serão machos e quantos serão fêmeas!"] }, at: "Corrida para o mar", m: "papel grande, lápis de cor", p: ["Desenhe uma praia à noite com a lua refletindo no mar e um ninho cheio de filhotes.", "Desenhe o caminho dos filhotes até a água e uma placa: “Apague as luzes da praia!”.", "Escreva no diário: “Mergulho 11: as tartarugas sempre voltam para casa”."], q: "Como você acha que podemos ajudar os filhotes de tartaruga?" },
en: { h: "On a moonlit night at the beach, Nina and Leo saw a group of people with red flashlights looking at the sand. Suddenly, tiny baby turtles started climbing out of a hole and racing to the sea! “They know the way by themselves,” Grandpa whispered, moved.", t: "Sea turtles", f: "Sea turtles live in the sea, but females return to the beach to dig nests and lay eggs in the sand. The babies hatch at night and race to the water, guided by the glow of the horizon. Many females return years later to lay eggs in the same area where they were born.", x: "The temperature of the sand decides whether a baby turtle will be male or female! Warmer sand makes more females, and cooler sand makes more males.", s: ["There are seven species of sea turtles in the world, and five of them nest in Brazil.", "Brazil's Tamar Project has protected sea turtles along the coast since 1980.", "Bright lights near the beach confuse the hatchlings, which may head the wrong way instead of toward the sea."], ex: { t: "Warm sand, cool sand", m: "two containers of sand or soil, a sunny spot, a shady spot", p: ["Put one container in the sun and the other in the shade for a few hours.", "Push your finger halfway into the sand in each. Which is warmer?", "In a turtle nest, that difference decides how many babies will be males and how many will be females!"] }, at: "Race to the sea", m: "large paper, colored pencils", p: ["Draw a beach at night with the moon reflecting on the sea and a nest full of hatchlings.", "Draw the hatchlings' path to the water and a sign: “Turn off the beach lights!”", "Write in your log: “Dive 11: turtles always come home.”"], q: "How do you think we can help baby turtles?" },
es: { h: "Una noche de luna en la playa, Nina y Leo vieron a un grupo de personas con linternas rojas mirando la arena. ¡De repente, tortuguitas bebé empezaron a salir de un hoyo y a correr hacia el mar! “Conocen el camino solas”, susurró el abuelo, emocionado.", t: "Las tortugas marinas", f: "Las tortugas marinas viven en el mar, pero las hembras vuelven a la playa para cavar nidos y poner huevos en la arena. Las crías nacen de noche y corren hacia el agua guiadas por el brillo del horizonte. Muchas hembras vuelven, años después, a poner huevos en la misma zona donde nacieron.", x: "¡La temperatura de la arena decide si la cría será macho o hembra! La arena más caliente produce más hembras, y la más fresca, más machos.", s: ["Existen siete especies de tortugas marinas en el mundo, y cinco de ellas anidan en Brasil.", "El Proyecto Tamar protege a las tortugas marinas en la costa brasileña desde 1980.", "Las luces fuertes cerca de la playa confunden a las crías, que pueden ir hacia el lado equivocado en vez de ir al mar."], ex: { t: "Arena caliente, arena fresca", m: "dos recipientes con arena o tierra, un lugar al sol, un lugar a la sombra", p: ["Pon un recipiente al sol y el otro a la sombra durante unas horas.", "Mete el dedo hasta la mitad en la arena de cada uno. ¿Cuál está más caliente?", "¡En un nido de tortuga, esa diferencia decide cuántas crías serán machos y cuántas hembras!"] }, at: "Carrera hacia el mar", m: "papel grande, lápices de colores", p: ["Dibuja una playa de noche con la luna reflejada en el mar y un nido lleno de crías.", "Dibuja el camino de las crías hasta el agua y un cartel: “¡Apaguen las luces de la playa!”.", "Escribe en el diario: “Inmersión 11: las tortugas siempre vuelven a casa”."], q: "¿Cómo crees que podemos ayudar a las crías de tortuga?" } },

{ e: "🪼", art: { b: "🪼", s: ["💧", "🌊", "✨", "⚠️"], c: ["#3A1B5A", "#9A6AD4"] },
pt: { h: "Na beira do mar, Leo viu uma bolha transparente na areia e foi pegar. O vovô segurou a mão dele na hora: “Cuidado, é uma água-viva! Mesmo na areia, ela pode queimar.” Leo olhou de longe, fascinado: “Mas onde fica a cara dela?” O vovô riu: “Ela não tem cara, nem cérebro!”", t: "As águas-vivas", f: "As águas-vivas são animais gelatinosos que flutuam no mar e se movem abrindo e fechando o corpo como um guarda-chuva. Elas não têm cérebro, coração nem ossos. Os tentáculos têm células que soltam pequenos ferrões para capturar comida e se defender.", x: "As águas-vivas existem há mais de 500 milhões de anos, muito antes dos dinossauros! E existe uma espécie que consegue voltar a ser “bebê” quando fica velha ou machucada, e por isso é chamada de água-viva imortal.", s: ["O corpo de uma água-viva é feito de cerca de 95% de água.", "Algumas águas-vivas brilham no escuro.", "Se uma água-viva queimar alguém, não se deve esfregar a pele: o certo é procurar um salva-vidas ou um adulto."], ex: { t: "Água-viva na garrafa", m: "uma garrafa transparente com água, um saquinho plástico bem fino, linha, tesoura, corante azul (opcional)", p: ["Corte um quadrado do saquinho, faça uma bolinha de ar no meio e amarre com linha, formando a “cabeça”.", "Corte a parte de baixo em tirinhas finas, que serão os tentáculos. Coloque um pouco de água dentro da cabeça para ela não boiar demais.", "Coloque dentro da garrafa com água azul, feche e vire devagar: a água-viva “nada” como uma de verdade!"] }, at: "Ficha de segurança na praia", m: "papel, lápis de cor", p: ["Desenhe uma água-viva bonita e, ao lado, uma placa de cuidado.", "Escreva três regras: não tocar, avisar um adulto e procurar o salva-vidas.", "Escreva no diário: “Mergulho 12: sem cérebro há 500 milhões de anos!”."], q: "Como seria viver sem cérebro e sem coração? O que você acha que a água-viva sente?" },
en: { h: "At the water's edge, Leo saw a clear blob on the sand and reached for it. Grandpa caught his hand right away: “Careful, it's a jellyfish! Even on the sand it can sting.” Leo looked from a distance, fascinated: “But where's its face?” Grandpa laughed: “It has no face, and no brain either!”", t: "Jellyfish", f: "Jellyfish are jelly-like animals that drift in the sea and move by opening and closing their bodies like umbrellas. They have no brain, heart or bones. Their tentacles have cells that fire tiny stingers to catch food and defend themselves.", x: "Jellyfish have existed for more than 500 million years, long before the dinosaurs! And there's one species that can turn back into a “baby” when it gets old or hurt, which is why it's called the immortal jellyfish.", s: ["A jellyfish's body is about 95% water.", "Some jellyfish glow in the dark.", "If a jellyfish stings someone, don't rub the skin: the right thing is to find a lifeguard or a grown-up."], ex: { t: "Jellyfish in a bottle", m: "a clear bottle of water, a very thin plastic bag, thread, scissors, blue coloring (optional)", p: ["Cut a square from the bag, make a little air bubble in the middle and tie it off with thread to form the “head.”", "Cut the bottom into thin strips for tentacles. Put a little water inside the head so it doesn't float too much.", "Put it in the bottle of blue water, close it and turn it slowly: the jellyfish “swims” like a real one!"] }, at: "Beach safety card", m: "paper, colored pencils", p: ["Draw a pretty jellyfish and, next to it, a caution sign.", "Write three rules: don't touch, tell a grown-up and find the lifeguard.", "Write in your log: “Dive 12: brainless for 500 million years!”"], q: "What would it be like to live without a brain or a heart? What do you think a jellyfish feels?" },
es: { h: "En la orilla del mar, Leo vio una burbuja transparente en la arena y fue a agarrarla. El abuelo le sujetó la mano enseguida: “¡Cuidado, es una medusa! Aunque esté en la arena, puede picar.” Leo la miró de lejos, fascinado: “¿Pero dónde tiene la cara?” El abuelo se rió: “¡No tiene cara, ni cerebro!”", t: "Las medusas", f: "Las medusas son animales gelatinosos que flotan en el mar y se mueven abriendo y cerrando el cuerpo como un paraguas. No tienen cerebro, corazón ni huesos. Sus tentáculos tienen células que disparan pequeños aguijones para atrapar comida y defenderse.", x: "¡Las medusas existen desde hace más de 500 millones de años, mucho antes que los dinosaurios! Y hay una especie que puede volver a ser “bebé” cuando envejece o se lastima, por eso la llaman medusa inmortal.", s: ["El cuerpo de una medusa es cerca de 95% agua.", "Algunas medusas brillan en la oscuridad.", "Si una medusa pica a alguien, no hay que frotar la piel: lo correcto es buscar a un guardavidas o a un adulto."], ex: { t: "Medusa en la botella", m: "una botella transparente con agua, una bolsita de plástico muy fina, hilo, tijera, colorante azul (opcional)", p: ["Corta un cuadrado de la bolsita, haz una burbujita de aire en el medio y átala con hilo para formar la “cabeza”.", "Corta la parte de abajo en tiritas finas, que serán los tentáculos. Pon un poco de agua dentro de la cabeza para que no flote demasiado.", "Ponla dentro de la botella con agua azul, ciérrala y dala vuelta despacio: ¡la medusa “nada” como una de verdad!"] }, at: "Ficha de seguridad en la playa", m: "papel, lápices de colores", p: ["Dibuja una medusa linda y, al lado, un cartel de precaución.", "Escribe tres reglas: no tocar, avisar a un adulto y buscar al guardavidas.", "Escribe en el diario: “Inmersión 12: ¡sin cerebro desde hace 500 millones de años!”."], q: "¿Cómo sería vivir sin cerebro y sin corazón? ¿Qué crees que siente una medusa?" } },

{ e: "⭐", art: { b: "⭐", s: ["🦔", "🐚", "👁️", "🪨"], c: ["#5A2A0B", "#E0703A"] },
pt: { h: "Numa poça de maré baixa, Nina encontrou uma estrela-do-mar laranja grudada numa pedra. Ela queria levar para casa, mas o vovô explicou que a estrela precisa da água para viver. “Vamos só observar”, disse. “Ela tem segredos incríveis, como um olho na ponta de cada braço!”", t: "Estrelas e ouriços-do-mar", f: "A estrela-do-mar não é peixe: ela é parente dos ouriços-do-mar e dos pepinos-do-mar. Ela anda devagar usando centenas de pezinhos embaixo dos braços, que funcionam como ventosas. Muitas estrelas têm cinco braços, mas algumas têm dezenas.", x: "Se uma estrela-do-mar perde um braço, um novo cresce no lugar! E para comer, algumas colocam o estômago para fora do corpo, digerem a comida e depois recolhem o estômago de volta.", s: ["Muitas estrelas-do-mar têm um olhinho simples na ponta de cada braço, que percebe luz e sombra.", "Os ouriços-do-mar têm espinhos para se proteger e uma boca embaixo do corpo com cinco dentinhos.", "Nunca tire estrelas-do-mar da água: elas podem morrer em poucos minutos fora do mar."], ex: { t: "Estrela de papel que se abre", m: "papel sulfite, tesoura, lápis de cor, um prato fundo com água", p: ["Desenhe e recorte uma estrela de cinco braços, e pinte um bichinho no centro.", "Dobre cada braço para o meio, fechando a estrela como uma flor fechada.", "Coloque a estrela fechada sobre a água: os braços se abrem sozinhos devagar! A água entra pelas fibras do papel e o desdobra."] }, at: "Poça de maré", m: "papel, lápis de cor", p: ["Desenhe uma poça de maré entre as pedras, cheia de vida.", "Coloque estrelas-do-mar, ouriços, siris, conchas e peixinhos.", "Escreva no diário: “Mergulho 13: braços que crescem de novo!”."], q: "Se você pudesse ter um superpoder da estrela-do-mar, qual escolheria?" },
en: { h: "In a low-tide pool, Nina found an orange starfish stuck to a rock. She wanted to take it home, but Grandpa explained that starfish need water to live. “Let's just watch,” he said. “It has amazing secrets, like an eye at the tip of each arm!”", t: "Starfish and sea urchins", f: "A starfish isn't a fish: it's related to sea urchins and sea cucumbers. It moves slowly using hundreds of tiny feet under its arms that work like suction cups. Many starfish have five arms, but some have dozens.", x: "If a starfish loses an arm, a new one grows back! And to eat, some push their stomachs out of their bodies, digest the food and then pull their stomachs back in.", s: ["Many starfish have a simple little eye at the tip of each arm that senses light and shadow.", "Sea urchins have spines for protection and a mouth underneath with five little teeth.", "Never take starfish out of the water: they can die within minutes out of the sea."], ex: { t: "Opening paper star", m: "printer paper, scissors, colored pencils, a deep plate of water", p: ["Draw and cut out a five-armed star, and color a little creature in the center.", "Fold each arm into the middle, closing the star like a shut flower.", "Set the closed star on the water: the arms slowly open by themselves! Water soaks into the paper fibers and unfolds it."] }, at: "Tide pool", m: "paper, colored pencils", p: ["Draw a tide pool among the rocks, full of life.", "Add starfish, sea urchins, crabs, shells and little fish.", "Write in your log: “Dive 13: arms that grow back!”"], q: "If you could have one starfish superpower, which would you choose?" },
es: { h: "En un charco de marea baja, Nina encontró una estrella de mar naranja pegada a una roca. Quería llevarla a casa, pero el abuelo le explicó que la estrella necesita el agua para vivir. “Solo vamos a mirarla”, dijo. “¡Tiene secretos increíbles, como un ojo en la punta de cada brazo!”", t: "Estrellas y erizos de mar", f: "La estrella de mar no es un pez: es pariente de los erizos y los pepinos de mar. Camina despacio usando cientos de piecitos debajo de los brazos, que funcionan como ventosas. Muchas estrellas tienen cinco brazos, pero algunas tienen decenas.", x: "¡Si una estrella de mar pierde un brazo, le crece uno nuevo! Y para comer, algunas sacan el estómago fuera del cuerpo, digieren la comida y después lo vuelven a guardar.", s: ["Muchas estrellas de mar tienen un ojito simple en la punta de cada brazo, que percibe la luz y la sombra.", "Los erizos de mar tienen espinas para protegerse y una boca debajo del cuerpo con cinco dientitos.", "Nunca saques estrellas de mar del agua: pueden morir en pocos minutos fuera del mar."], ex: { t: "Estrella de papel que se abre", m: "papel de impresora, tijera, lápices de colores, un plato hondo con agua", p: ["Dibuja y recorta una estrella de cinco brazos, y pinta un bichito en el centro.", "Dobla cada brazo hacia el medio, cerrando la estrella como una flor cerrada.", "Pon la estrella cerrada sobre el agua: ¡los brazos se abren solos, despacio! El agua entra en las fibras del papel y lo despliega."] }, at: "Charco de marea", m: "papel, lápices de colores", p: ["Dibuja un charco de marea entre las rocas, lleno de vida.", "Pon estrellas de mar, erizos, cangrejos, conchas y pececitos.", "Escribe en el diario: “Inmersión 13: ¡brazos que vuelven a crecer!”."], q: "Si pudieras tener un superpoder de la estrella de mar, ¿cuál elegirías?" } },

{ e: "🦀", art: { b: "🦀", s: ["🐚", "🦞", "🏖️", "🦐"], c: ["#5A1B0B", "#E0503A"] },
pt: { h: "Na areia, Leo seguiu um siri que andava de lado, rapidinho, até se esconder num buraco. Logo depois, Nina viu uma concha andando sozinha! “É um caranguejo-ermitão”, explicou o vovô. “Ele usa conchas vazias como casa e troca de casa quando cresce.”", t: "Caranguejos e companhia", f: "Caranguejos, siris, lagostas e camarões são crustáceos: animais com uma armadura dura por fora do corpo, chamada exoesqueleto. Como a armadura não cresce, eles precisam trocá-la de tempos em tempos. Eles soltam a casca velha e ficam moles até a nova endurecer.", x: "Os caranguejos-ermitões às vezes formam filas por tamanho para trocar de concha todos ao mesmo tempo: quando um se muda para uma concha maior, o próximo pega a que ficou vazia!", s: ["Os caranguejos andam de lado porque as juntas das pernas dobram melhor para os lados.", "Nos manguezais do Brasil, o caranguejo-uçá é muito importante para a natureza e para as comunidades que vivem ali.", "Alguns caranguejos-aranha do Japão podem ter pernas que somam quase 4 metros de ponta a ponta."], ex: { t: "Corrida de caranguejo", m: "um corredor ou espaço estreito, giz ou fita para marcar, um cronômetro", p: ["Marque uma pista estreita, de uns 3 passos de largura.", "Corra a pista de frente e depois andando de lado, como um caranguejo. Cronometre as duas.", "Num lugar apertado, entre pedras, andar de lado pode ser muito mais prático!"] }, at: "Casa nova para o ermitão", m: "papel, lápis de cor", p: ["Desenhe três conchas de tamanhos diferentes, uma ao lado da outra.", "Desenhe caranguejos-ermitões em fila esperando para trocar de casa, do menor para o maior.", "Escreva no diário: “Mergulho 14: armaduras que se trocam”."], q: "Se você pudesse trocar de casa como o ermitão, como seria a sua próxima casa?" },
en: { h: "On the sand, Leo followed a crab scuttling sideways, fast, until it hid in a hole. Right after, Nina saw a shell walking by itself! “It's a hermit crab,” Grandpa explained. “It uses empty shells as a home and moves to a new one when it grows.”", t: "Crabs and company", f: "Crabs, lobsters and shrimp are crustaceans: animals with hard armor on the outside of their bodies, called an exoskeleton. Since the armor doesn't grow, they have to replace it now and then. They shed the old shell and stay soft until the new one hardens.", x: "Hermit crabs sometimes line up by size to swap shells all at once: when one moves into a bigger shell, the next one takes the one it left behind!", s: ["Crabs walk sideways because their leg joints bend best to the side.", "In Brazil's mangroves, the mangrove crab is very important to nature and to the communities that live there.", "Some Japanese spider crabs have legs that span almost 4 meters (13 feet) from tip to tip."], ex: { t: "Crab race", m: "a hallway or narrow space, chalk or tape to mark lines, a stopwatch", p: ["Mark out a narrow track about 3 steps wide.", "Run the track facing forward and then moving sideways like a crab. Time both.", "In a tight space between rocks, walking sideways can be much handier!"] }, at: "A new home for the hermit crab", m: "paper, colored pencils", p: ["Draw three shells of different sizes in a row.", "Draw hermit crabs lined up to swap homes, from smallest to biggest.", "Write in your log: “Dive 14: armor that gets swapped.”"], q: "If you could swap houses like a hermit crab, what would your next home be like?" },
es: { h: "En la arena, Leo siguió a un cangrejo que caminaba de costado, rapidito, hasta esconderse en un hoyo. ¡Enseguida Nina vio una concha caminando sola! “Es un cangrejo ermitaño”, explicó el abuelo. “Usa conchas vacías como casa y se muda cuando crece.”", t: "Cangrejos y compañía", f: "Los cangrejos, las langostas y los camarones son crustáceos: animales con una armadura dura por fuera del cuerpo, llamada exoesqueleto. Como la armadura no crece, tienen que cambiarla cada tanto. Se sacan la cáscara vieja y quedan blanditos hasta que la nueva se endurece.", x: "¡Los cangrejos ermitaños a veces hacen fila por tamaño para cambiar de concha todos a la vez: cuando uno se muda a una concha más grande, el siguiente toma la que quedó vacía!", s: ["Los cangrejos caminan de costado porque las articulaciones de sus patas se doblan mejor hacia los lados.", "En los manglares de Brasil, el cangrejo de manglar es muy importante para la naturaleza y para las comunidades que viven allí.", "Algunos cangrejos araña de Japón tienen patas que suman casi 4 metros de punta a punta."], ex: { t: "Carrera de cangrejos", m: "un pasillo o espacio angosto, tiza o cinta para marcar, un cronómetro", p: ["Marca una pista angosta, de unos 3 pasos de ancho.", "Corre la pista de frente y después caminando de costado, como un cangrejo. Cronometra las dos.", "¡En un lugar apretado, entre rocas, caminar de costado puede ser mucho más práctico!"] }, at: "Casa nueva para el ermitaño", m: "papel, lápices de colores", p: ["Dibuja tres conchas de distintos tamaños, una al lado de la otra.", "Dibuja cangrejos ermitaños en fila esperando para cambiar de casa, del más chico al más grande.", "Escribe en el diario: “Inmersión 14: armaduras que se cambian”."], q: "Si pudieras cambiar de casa como el ermitaño, ¿cómo sería tu próxima casa?" } },

{ e: "🐴", art: { b: "🐴", s: ["🌿", "👨‍🍼", "🫧", "🐠"], c: ["#4E3A0B", "#E0B03A"] },
pt: { h: "No aquário, Nina se apaixonou por um cavalo-marinho agarrado numa alga pelo rabinho. “Que bichinho estranho e lindo!”, disse. O vovô contou a coisa mais surpreendente da noite: “Sabem quem fica grávido no cavalo-marinho? O papai!”. Leo achou que era brincadeira.", t: "Os cavalos-marinhos", f: "O cavalo-marinho é um peixe, mesmo parecendo um cavalinho. Ele nada em pé, devagar, batendo uma nadadeira pequena nas costas. Usa a cauda para se segurar em algas e corais e se camufla mudando de cor. Os olhos se mexem cada um para um lado, ao mesmo tempo.", x: "No cavalo-marinho, é o macho que carrega os ovos numa bolsa na barriga até os filhotes nascerem! Ele pode “dar à luz” centenas de filhotinhos de uma vez.", s: ["Os cavalos-marinhos estão entre os peixes mais lentos do mundo.", "Os cientistas descobriram que a cauda do cavalo-marinho tem formato quadrado, o que a deixa mais forte e melhor para agarrar.", "Muitos cavalos-marinhos formam casais que se cumprimentam todo dia com uma pequena dança."], ex: { t: "Cauda quadrada x cauda redonda", m: "duas folhas de papel, fita adesiva, livros", p: ["Enrole uma folha num tubo redondo e dobre a outra num tubo quadrado, do mesmo tamanho, e prenda com fita.", "Deite os dois tubos na mesa e aperte de leve com a mão. Depois coloque um livro em cima de cada um.", "Qual amassa menos? O formato quadrado aguenta melhor ser apertado, como a cauda do cavalo-marinho!"] }, at: "Família cavalo-marinho", m: "papel, lápis de cor", p: ["Desenhe um papai cavalo-marinho com a bolsa cheia de filhotinhos.", "Desenhe os filhotes saindo e se segurando nas algas pela cauda.", "Escreva no diário: “Mergulho 15: o papai é quem tem os bebês!”."], q: "O que você acha mais surpreendente no cavalo-marinho?" },
en: { h: "At the aquarium, Nina fell in love with a seahorse holding onto a piece of seaweed with its little tail. “What a strange, beautiful creature!” she said. Grandpa shared the most surprising fact of the night: “Do you know who gets pregnant in seahorses? The dad!” Leo thought he was joking.", t: "Seahorses", f: "A seahorse is a fish, even though it looks like a little horse. It swims upright, slowly, by fluttering a small fin on its back. It uses its tail to hold onto seaweed and coral, and it camouflages by changing color. Its eyes move independently, each looking a different way at the same time.", x: "In seahorses, it's the male that carries the eggs in a pouch on his belly until they hatch! He can “give birth” to hundreds of babies at once.", s: ["Seahorses are among the slowest fish in the world.", "Scientists found that a seahorse's tail is square-shaped, which makes it stronger and better for gripping.", "Many seahorses form pairs that greet each other every day with a little dance."], ex: { t: "Square tail vs. round tail", m: "two sheets of paper, tape, books", p: ["Roll one sheet into a round tube and fold the other into a square tube of the same size, and tape them.", "Lay both tubes on the table and press gently with your hand. Then put a book on each.", "Which one crushes less? The square shape handles squeezing better, like a seahorse's tail!"] }, at: "Seahorse family", m: "paper, colored pencils", p: ["Draw a seahorse dad with a pouch full of tiny babies.", "Draw the babies coming out and holding onto seaweed with their tails.", "Write in your log: “Dive 15: Dad is the one who has the babies!”"], q: "What do you find most surprising about seahorses?" },
es: { h: "En el acuario, Nina se enamoró de un caballito de mar agarrado a un alga con su colita. “¡Qué bichito raro y lindo!”, dijo. El abuelo contó lo más sorprendente de la noche: “¿Saben quién queda embarazado en los caballitos de mar? ¡El papá!”. Leo pensó que era una broma.", t: "Los caballitos de mar", f: "El caballito de mar es un pez, aunque parezca un caballito. Nada de pie, despacio, moviendo una aleta pequeña en la espalda. Usa la cola para sujetarse a algas y corales y se camufla cambiando de color. Sus ojos se mueven cada uno para un lado, al mismo tiempo.", x: "¡En los caballitos de mar, es el macho el que lleva los huevos en una bolsa en la panza hasta que nacen las crías! Puede “dar a luz” a cientos de crías de una vez.", s: ["Los caballitos de mar están entre los peces más lentos del mundo.", "Los científicos descubrieron que la cola del caballito de mar tiene forma cuadrada, lo que la hace más fuerte y mejor para agarrar.", "Muchos caballitos de mar forman parejas que se saludan todos los días con un pequeño baile."], ex: { t: "Cola cuadrada vs. cola redonda", m: "dos hojas de papel, cinta adhesiva, libros", p: ["Enrolla una hoja en un tubo redondo y dobla la otra en un tubo cuadrado, del mismo tamaño, y sujétalos con cinta.", "Acuesta los dos tubos en la mesa y apriétalos suavemente con la mano. Después pon un libro encima de cada uno.", "¿Cuál se aplasta menos? ¡La forma cuadrada aguanta mejor los apretones, como la cola del caballito de mar!"] }, at: "Familia caballito de mar", m: "papel, lápices de colores", p: ["Dibuja un papá caballito de mar con la bolsa llena de crías.", "Dibuja a las crías saliendo y agarrándose a las algas con la cola.", "Escribe en el diario: “Inmersión 15: ¡el papá es quien tiene los bebés!”."], q: "¿Qué te parece lo más sorprendente del caballito de mar?" } },

{ e: "🌱", art: { b: "🌳", s: ["🦀", "🐟", "🪶", "💧"], c: ["#2A3A1B", "#6A8A3A"] },
pt: { h: "O barco passou por um lugar onde as árvores cresciam dentro da água, com raízes compridas que pareciam pernas. Leo achou que as árvores estavam andando! “É um manguezal”, explicou o vovô. “Um berçário do mar, onde muitos peixes e caranguejos nascem e crescem.”", t: "Os manguezais", f: "Os manguezais são florestas que crescem onde os rios encontram o mar, numa mistura de água doce e salgada. As árvores do mangue têm raízes especiais que ficam para fora da lama para respirar. Entre essas raízes, filhotes de peixes, camarões e caranguejos se escondem dos predadores.", x: "O Brasil tem uma das maiores áreas de manguezal do mundo! Muitos dos peixes e camarões que vão parar no prato das pessoas passaram a infância num mangue.", s: ["As raízes do mangue seguram a lama e protegem a costa das ondas e das tempestades.", "Os manguezais guardam muito carbono na lama, ajudando a combater o aquecimento do planeta.", "Muitas comunidades vivem da pesca e da coleta de caranguejos nos manguezais."], ex: { t: "Filtro do mangue", m: "uma garrafa PET cortada ao meio (com um adulto), algodão ou pano, areia, pedrinhas, água suja com terra", p: ["Vire a parte de cima da garrafa de cabeça para baixo dentro da parte de baixo, como um funil.", "Coloque em camadas: algodão, areia e pedrinhas por cima.", "Despeje a água suja devagar e veja sair mais limpinha embaixo! As raízes e a lama do mangue também ajudam a filtrar a água. Atenção: essa água não é para beber."] }, at: "Berçário do mar", m: "papel, lápis de cor", p: ["Desenhe árvores de mangue com raízes compridas dentro da água e da lama.", "Esconda entre as raízes filhotes de peixe, caranguejos e camarões, e desenhe uma garça pescando.", "Escreva no diário: “Mergulho 16: o mangue é o berçário do mar”."], q: "Por que você acha que tantos filhotes escolhem o mangue para crescer?" },
en: { h: "The boat passed a place where trees grew right in the water, with long roots that looked like legs. Leo thought the trees were walking! “It's a mangrove forest,” Grandpa explained. “A nursery of the sea, where lots of fish and crabs are born and grow up.”", t: "Mangroves", f: "Mangroves are forests that grow where rivers meet the sea, in a mix of fresh and salt water. Mangrove trees have special roots that stick up out of the mud to breathe. Among those roots, baby fish, shrimp and crabs hide from predators.", x: "Brazil has one of the largest mangrove areas in the world! Many of the fish and shrimp that end up on people's plates spent their childhood in a mangrove.", s: ["Mangrove roots hold the mud in place and protect the coast from waves and storms.", "Mangroves store lots of carbon in their mud, helping fight global warming.", "Many communities make a living fishing and gathering crabs in the mangroves."], ex: { t: "Mangrove filter", m: "a plastic bottle cut in half (by a grown-up), cotton or cloth, sand, pebbles, muddy water", p: ["Turn the top half of the bottle upside down into the bottom half, like a funnel.", "Add layers: cotton, then sand, then pebbles on top.", "Slowly pour in the muddy water and watch it come out cleaner below! Mangrove roots and mud help filter water too. Note: this water is not for drinking."] }, at: "Nursery of the sea", m: "paper, colored pencils", p: ["Draw mangrove trees with long roots in the water and mud.", "Hide baby fish, crabs and shrimp among the roots, and draw a heron fishing.", "Write in your log: “Dive 16: the mangrove is the sea's nursery.”"], q: "Why do you think so many babies choose the mangroves to grow up in?" },
es: { h: "El barco pasó por un lugar donde los árboles crecían dentro del agua, con raíces largas que parecían piernas. ¡Leo pensó que los árboles estaban caminando! “Es un manglar”, explicó el abuelo. “Una guardería del mar, donde nacen y crecen muchos peces y cangrejos.”", t: "Los manglares", f: "Los manglares son bosques que crecen donde los ríos se encuentran con el mar, en una mezcla de agua dulce y salada. Los árboles del manglar tienen raíces especiales que quedan fuera del barro para respirar. Entre esas raíces, crías de peces, camarones y cangrejos se esconden de los depredadores.", x: "¡Brasil tiene una de las mayores áreas de manglar del mundo! Muchos de los peces y camarones que terminan en el plato de las personas pasaron su infancia en un manglar.", s: ["Las raíces del manglar sostienen el barro y protegen la costa de las olas y las tormentas.", "Los manglares guardan mucho carbono en el barro, ayudando a combatir el calentamiento del planeta.", "Muchas comunidades viven de la pesca y la recolección de cangrejos en los manglares."], ex: { t: "Filtro del manglar", m: "una botella de plástico cortada por la mitad (con un adulto), algodón o tela, arena, piedritas, agua sucia con tierra", p: ["Pon la parte de arriba de la botella boca abajo dentro de la parte de abajo, como un embudo.", "Pon en capas: algodón, arena y piedritas arriba.", "Echa el agua sucia despacio y mira cómo sale más limpia abajo. Las raíces y el barro del manglar también ayudan a filtrar el agua. Atención: esa agua no es para tomar."] }, at: "Guardería del mar", m: "papel, lápices de colores", p: ["Dibuja árboles de manglar con raíces largas dentro del agua y el barro.", "Esconde entre las raíces crías de peces, cangrejos y camarones, y dibuja una garza pescando.", "Escribe en el diario: “Inmersión 16: el manglar es la guardería del mar”."], q: "¿Por qué crees que tantas crías eligen el manglar para crecer?" } },

{ e: "🔦", art: { b: "🐡", s: ["💡", "🦑", "✨", "🌑"], c: ["#0B0B1B", "#2A2A5A"] },
pt: { h: "O vovô apagou todas as luzes e acendeu uma lanterna pequenininha na frente do rosto. “Bem-vindos à zona da meia-noite”, disse com voz de mistério. “Aqui embaixo, os animais acendem suas próprias luzes. E um peixe usa uma lanterna na testa para pescar!”", t: "As criaturas do mar profundo", f: "No fundo do mar, onde a luz do Sol não chega, vivem animais muito estranhos. Muitos produzem a própria luz, num fenômeno chamado bioluminescência. O peixe-diabo, por exemplo, tem uma “vara de pescar” com uma luzinha na ponta para atrair presas até a sua boca enorme.", x: "A maioria dos animais do fundo do mar consegue produzir luz! Eles usam a luz para atrair comida, encontrar parceiros, se esconder ou assustar predadores.", s: ["Muitos animais do fundo são vermelhos, porque a luz vermelha não chega lá embaixo e eles ficam invisíveis.", "Há peixes no fundo do mar com dentes tão grandes que não conseguem fechar a boca.", "Os cientistas ainda descobrem espécies novas toda vez que exploram o mar profundo."], ex: { t: "O vermelho que some", m: "objetos vermelhos e azuis, papel celofane azul ou um plástico azul transparente, uma lanterna, um quarto escuro", p: ["No quarto escuro, ilumine os objetos com a lanterna coberta pelo celofane azul.", "Observe: os objetos vermelhos ficam escuros, quase pretos, e os azuis continuam visíveis.", "No fundo do mar só sobra luz azulada, por isso ser vermelho é como usar uma capa de invisibilidade!"] }, at: "Monstro do fundo do mar", m: "papel preto, giz de cera ou lápis claros, cola com glitter (opcional)", p: ["Invente uma criatura do fundo do mar com luzinhas no corpo.", "Desenhe no papel preto com cores claras, como se ela estivesse brilhando no escuro.", "Escreva no diário: “Mergulho 17: no escuro, os animais fazem a própria luz”."], q: "Se você vivesse no escuro total, que superpoder gostaria de ter?" },
en: { h: "Grandpa turned off all the lights and switched on a tiny flashlight in front of his face. “Welcome to the midnight zone,” he said in a mysterious voice. “Down here, animals turn on their own lights. And one fish uses a lantern on its forehead to go fishing!”", t: "Creatures of the deep sea", f: "Deep in the sea, where sunlight never reaches, live some very strange animals. Many make their own light, something called bioluminescence. The anglerfish, for example, has a “fishing rod” with a little light at the tip to lure prey right up to its huge mouth.", x: "Most deep-sea animals can make light! They use it to attract food, find mates, hide or scare off predators.", s: ["Many deep-sea animals are red, because red light doesn't reach that far down, so they become invisible.", "Some deep-sea fish have teeth so big they can't close their mouths.", "Scientists still discover new species every time they explore the deep sea."], ex: { t: "The red that disappears", m: "red and blue objects, blue cellophane or clear blue plastic, a flashlight, a dark room", p: ["In the dark room, light up the objects with the flashlight covered in blue cellophane.", "Look: the red objects turn dark, almost black, while the blue ones stay visible.", "In the deep sea only bluish light is left, so being red is like wearing an invisibility cloak!"] }, at: "Deep-sea monster", m: "black paper, crayons or light-colored pencils, glitter glue (optional)", p: ["Invent a deep-sea creature with little lights on its body.", "Draw it on the black paper in light colors, as if it were glowing in the dark.", "Write in your log: “Dive 17: in the dark, animals make their own light.”"], q: "If you lived in total darkness, what superpower would you want?" },
es: { h: "El abuelo apagó todas las luces y encendió una linterna chiquitita frente a su cara. “Bienvenidos a la zona de medianoche”, dijo con voz misteriosa. “Aquí abajo, los animales encienden sus propias luces. ¡Y un pez usa una linterna en la frente para pescar!”", t: "Las criaturas del mar profundo", f: "En el fondo del mar, donde la luz del Sol no llega, viven animales muy extraños. Muchos producen su propia luz, un fenómeno llamado bioluminiscencia. El pez rape abisal, por ejemplo, tiene una “caña de pescar” con una lucecita en la punta para atraer presas hasta su boca enorme.", x: "¡La mayoría de los animales del fondo del mar puede producir luz! La usan para atraer comida, encontrar pareja, esconderse o asustar a los depredadores.", s: ["Muchos animales del fondo son rojos, porque la luz roja no llega tan abajo y así quedan invisibles.", "Hay peces del fondo del mar con dientes tan grandes que no pueden cerrar la boca.", "Los científicos descubren especies nuevas cada vez que exploran el mar profundo."], ex: { t: "El rojo que desaparece", m: "objetos rojos y azules, papel celofán azul o un plástico azul transparente, una linterna, un cuarto oscuro", p: ["En el cuarto oscuro, ilumina los objetos con la linterna cubierta con el celofán azul.", "Observa: los objetos rojos se ven oscuros, casi negros, y los azules siguen visibles.", "En el fondo del mar solo queda luz azulada, ¡así que ser rojo es como usar una capa de invisibilidad!"] }, at: "Monstruo del fondo del mar", m: "papel negro, crayones o lápices claros, plasticola con brillantina (opcional)", p: ["Inventa una criatura del fondo del mar con lucecitas en el cuerpo.", "Dibújala en el papel negro con colores claros, como si brillara en la oscuridad.", "Escribe en el diario: “Inmersión 17: en la oscuridad, los animales hacen su propia luz”."], q: "Si vivieras en la oscuridad total, ¿qué superpoder te gustaría tener?" } },

{ e: "⬇️", art: { b: "🫙", s: ["💧", "⬇️", "🌊", "🐟"], c: ["#0B1B4E", "#2A4AA0"] },
pt: { h: "Leo mergulhou até o fundo da piscina e voltou reclamando de uma pressão nos ouvidos. “Parece que a água está me apertando!”, disse. “E está mesmo”, respondeu o vovô. “Imagina lá no fundo do oceano, com quilômetros de água em cima!”", t: "A pressão das profundezas", f: "A água é pesada. Quanto mais fundo você desce, mais água fica em cima de você, e mais ela aperta tudo. Isso se chama pressão. A cada 10 metros de profundidade, a pressão aumenta como se outra atmosfera inteira fosse colocada em cima.", x: "No fundo da Fossa das Marianas, a pressão é mais de mil vezes maior que na superfície! Seria como ter vários elefantes em pé em cima de um selo de carta.", s: ["Copos de isopor levados até o fundo do mar voltam encolhidos, pequenininhos, por causa da pressão.", "Os animais do fundo do mar têm corpos moles e cheios de água, que aguentam bem a pressão.", "Os submarinos que vão bem fundo têm paredes grossíssimas de metal."], ex: { t: "Garrafa dos três jatos", m: "uma garrafa PET, um prego ou ponta de tesoura (com um adulto), fita adesiva, água, uma pia ou o quintal", p: ["Com um adulto, faça três furinhos na garrafa, um embaixo do outro: perto do fundo, no meio e mais em cima.", "Tampe os furos com uma tira de fita, encha a garrafa de água e coloque na pia.", "Puxe a fita: o jato de baixo vai mais longe! Lá embaixo tem mais água em cima, então a pressão é maior."] }, at: "Elevador para o abismo", m: "papel comprido, lápis de cor", p: ["Desenhe um elevador descendo pelo mar e marque as paradas: 10 metros, 200, mil, 4 mil e 11 mil metros.", "Em cada parada, desenhe o que você veria e uma setinha mostrando a pressão aumentando.", "Escreva no diário: “Mergulho 18: quanto mais fundo, mais aperta!”."], q: "Você teria coragem de descer até o ponto mais fundo do oceano?" },
en: { h: "Leo dove to the bottom of the pool and came back up complaining of pressure in his ears. “It feels like the water is squeezing me!” he said. “It really is,” Grandpa answered. “Imagine the bottom of the ocean, with kilometers of water on top!”", t: "The pressure of the deep", f: "Water is heavy. The deeper you go, the more water there is above you, and the harder it squeezes everything. That's called pressure. Every 10 meters (33 feet) of depth, the pressure increases as if another whole atmosphere were piled on top.", x: "At the bottom of the Mariana Trench, the pressure is more than a thousand times greater than at the surface! It would be like having several elephants standing on a postage stamp.", s: ["Foam cups taken to the bottom of the sea come back shrunken and tiny because of the pressure.", "Deep-sea animals have soft, water-filled bodies that handle the pressure well.", "Submarines that go very deep have extremely thick metal walls."], ex: { t: "Three-jet bottle", m: "a plastic bottle, a nail or scissor tip (with a grown-up), tape, water, a sink or yard", p: ["With a grown-up, poke three small holes in the bottle, one above the other: near the bottom, in the middle and higher up.", "Cover the holes with a strip of tape, fill the bottle with water and set it in the sink.", "Pull off the tape: the bottom jet shoots farthest! Down there, more water is pressing from above, so the pressure is greater."] }, at: "Elevator to the abyss", m: "long paper, colored pencils", p: ["Draw an elevator going down through the sea and mark the stops: 10 meters, 200, 1,000, 4,000 and 11,000 meters.", "At each stop, draw what you'd see and a little arrow showing the pressure increasing.", "Write in your log: “Dive 18: the deeper you go, the harder it squeezes!”"], q: "Would you be brave enough to go down to the deepest point in the ocean?" },
es: { h: "Leo buceó hasta el fondo de la pileta y volvió quejándose de una presión en los oídos. “¡Parece que el agua me aprieta!”, dijo. “Así es”, respondió el abuelo. “¡Imagínate allá en el fondo del océano, con kilómetros de agua encima!”", t: "La presión de las profundidades", f: "El agua es pesada. Cuanto más profundo bajas, más agua tienes encima y más aprieta todo. Eso se llama presión. Cada 10 metros de profundidad, la presión aumenta como si se agregara otra atmósfera entera encima.", x: "¡En el fondo de la fosa de las Marianas, la presión es más de mil veces mayor que en la superficie! Sería como tener varios elefantes parados sobre una estampilla.", s: ["Los vasos de telgopor llevados al fondo del mar vuelven encogidos, chiquititos, por la presión.", "Los animales del fondo del mar tienen cuerpos blandos y llenos de agua, que aguantan bien la presión.", "Los submarinos que bajan muy profundo tienen paredes de metal gruesísimas."], ex: { t: "Botella de los tres chorros", m: "una botella de plástico, un clavo o punta de tijera (con un adulto), cinta adhesiva, agua, una pileta o el patio", p: ["Con un adulto, haz tres agujeritos en la botella, uno debajo del otro: cerca del fondo, en el medio y más arriba.", "Tapa los agujeros con una tira de cinta, llena la botella de agua y ponla en la pileta.", "Saca la cinta: ¡el chorro de abajo llega más lejos! Abajo hay más agua encima, así que la presión es mayor."] }, at: "Ascensor al abismo", m: "papel largo, lápices de colores", p: ["Dibuja un ascensor bajando por el mar y marca las paradas: 10 metros, 200, 1.000, 4.000 y 11.000 metros.", "En cada parada, dibuja lo que verías y una flechita que muestre la presión aumentando.", "Escribe en el diario: “Inmersión 18: ¡cuanto más profundo, más aprieta!”."], q: "¿Te animarías a bajar hasta el punto más profundo del océano?" } },

{ e: "🚢", art: { b: "🚢", s: ["🤿", "🤖", "📡", "🔦"], c: ["#1B2A3A", "#E0A02C"] },
pt: { h: "Leo sentou no submarino de papelão e anunciou: “Vou descer até o ponto mais fundo do mundo!”. O vovô contou que, em 1960, duas pessoas já tinham feito isso de verdade, num submarino chamado Trieste. “Mas a viagem levou horas, e a janelinha era menor que a sua mão”, disse.", t: "Explorando as profundezas", f: "Para explorar o fundo do mar, as pessoas usam submarinos, que afundam enchendo tanques com água e sobem esvaziando esses tanques com ar. Hoje também existem robôs submarinos, controlados de navios, que descem com câmeras e braços mecânicos para estudar lugares muito fundos.", x: "Em 1960, Jacques Piccard e Don Walsh chegaram ao fundo da Fossa das Marianas, a quase 11 quilômetros de profundidade. Em 2012, o cineasta James Cameron fez essa viagem sozinho!", s: ["Os tanques que ajudam o submarino a subir e descer se chamam tanques de lastro.", "Os robôs submarinos podem ficar muitas horas no fundo, enquanto os cientistas assistem tudo pelo vídeo.", "Ainda conhecemos melhor a superfície da Lua do que muitas partes do fundo do nosso oceano."], ex: { t: "Submarino de garrafa", m: "uma garrafinha de plástico com tampa, moedas, fita adesiva, uma bacia com água", p: ["Prenda algumas moedas com fita na lateral da garrafinha vazia e fechada. Coloque na água: ela boia.", "Agora encha um pouco a garrafinha com água e teste de novo. Vá colocando mais água até ela afundar devagar.", "Tire um pouco de água e ela volta a subir. É assim que os submarinos usam os tanques de lastro!"] }, at: "Meu robô submarino", m: "papel, lápis de cor", p: ["Projete um robô submarino com câmeras, luzes, braços e uma cesta para coletar amostras.", "Dê um nome para ele e escreva até que profundidade ele consegue ir.", "Escreva no diário: “Mergulho 19: chegamos ao fundo do mundo!”."], q: "O que você gostaria que o seu robô submarino encontrasse?" },
en: { h: "Leo sat in the cardboard submarine and announced, “I'm going down to the deepest point in the world!” Grandpa said that in 1960 two people had really done it, in a submarine called Trieste. “But the trip took hours, and the little window was smaller than your hand,” he said.", t: "Exploring the depths", f: "To explore the sea floor, people use submarines, which sink by filling tanks with water and rise by emptying those tanks with air. Today there are also underwater robots, controlled from ships, that dive with cameras and mechanical arms to study very deep places.", x: "In 1960, Jacques Piccard and Don Walsh reached the bottom of the Mariana Trench, almost 11 kilometers (7 miles) down. In 2012, filmmaker James Cameron made the trip alone!", s: ["The tanks that help a submarine go up and down are called ballast tanks.", "Underwater robots can stay at the bottom for many hours while scientists watch everything on video.", "We still know the surface of the Moon better than many parts of our own ocean floor."], ex: { t: "Bottle submarine", m: "a small plastic bottle with a cap, coins, tape, a basin of water", p: ["Tape some coins to the side of the empty, capped bottle. Put it in the water: it floats.", "Now fill the bottle a little with water and test again. Keep adding water until it slowly sinks.", "Pour out a bit of water and it rises again. That's how submarines use their ballast tanks!"] }, at: "My underwater robot", m: "paper, colored pencils", p: ["Design an underwater robot with cameras, lights, arms and a basket for collecting samples.", "Name it and write how deep it can go.", "Write in your log: “Dive 19: we reached the bottom of the world!”"], q: "What would you like your underwater robot to find?" },
es: { h: "Leo se sentó en el submarino de cartón y anunció: “¡Voy a bajar al punto más profundo del mundo!”. El abuelo contó que, en 1960, dos personas ya lo habían hecho de verdad, en un submarino llamado Trieste. “Pero el viaje duró horas, y la ventanita era más chica que tu mano”, dijo.", t: "Explorando las profundidades", f: "Para explorar el fondo del mar, las personas usan submarinos, que se hunden llenando tanques con agua y suben vaciando esos tanques con aire. Hoy también existen robots submarinos, controlados desde barcos, que bajan con cámaras y brazos mecánicos para estudiar lugares muy profundos.", x: "¡En 1960, Jacques Piccard y Don Walsh llegaron al fondo de la fosa de las Marianas, a casi 11 kilómetros de profundidad! En 2012, el cineasta James Cameron hizo ese viaje solo.", s: ["Los tanques que ayudan al submarino a subir y bajar se llaman tanques de lastre.", "Los robots submarinos pueden quedarse muchas horas en el fondo mientras los científicos miran todo por video.", "Todavía conocemos mejor la superficie de la Luna que muchas partes del fondo de nuestro océano."], ex: { t: "Submarino de botella", m: "una botellita de plástico con tapa, monedas, cinta adhesiva, una palangana con agua", p: ["Pega algunas monedas con cinta al costado de la botellita vacía y cerrada. Ponla en el agua: flota.", "Ahora llena un poco la botellita con agua y prueba otra vez. Ve agregando agua hasta que se hunda despacio.", "Saca un poco de agua y vuelve a subir. ¡Así usan los submarinos los tanques de lastre!"] }, at: "Mi robot submarino", m: "papel, lápices de colores", p: ["Diseña un robot submarino con cámaras, luces, brazos y una canasta para recoger muestras.", "Ponle un nombre y escribe hasta qué profundidad puede llegar.", "Escribe en el diario: “Inmersión 19: ¡llegamos al fondo del mundo!”."], q: "¿Qué te gustaría que encontrara tu robot submarino?" } },

{ e: "🔄", art: { b: "🔄", s: ["🦆", "🍾", "🌡️", "🌊"], c: ["#0B3A5A", "#E0602C"] },
pt: { h: "Na praia, Nina achou uma garrafa com um bilhete dentro, escrito em outra língua! “Como ela chegou aqui?”, perguntou, encantada. “O mar tem estradas invisíveis”, explicou o vovô. “São as correntes marinhas, que levam água, animais e até garrafas pelo mundo.”", t: "As correntes marinhas", f: "O oceano não fica parado: ele tem correntes, como rios gigantes dentro do mar. Algumas são quentes, outras são frias. Elas são movidas pelo vento, pela rotação da Terra e pelas diferenças de temperatura e de sal da água. As correntes espalham calor pelo planeta e ajudam a formar o clima.", x: "Em 1992, um navio perdeu no Oceano Pacífico milhares de patinhos e bichinhos de borracha. Por muitos anos, eles foram aparecendo em praias do mundo inteiro, e os cientistas usaram isso para estudar as correntes!", s: ["Uma corrente quente que vem do Equador passa pelo litoral brasileiro em direção ao sul.", "Tartarugas, baleias e larvas de peixes usam as correntes como esteiras para viajar.", "Lixo jogado no mar também é levado pelas correntes e se acumula em certos lugares do oceano."], ex: { t: "Corrente quente, corrente fria", m: "um pote transparente com água morna, cubos de gelo feitos com água e corante azul", p: ["Encha o pote com água morna da torneira e espere a água ficar parada.", "Coloque um cubo de gelo azul com cuidado num canto.", "Observe: a água azul e fria desce para o fundo e se espalha, enquanto a morna fica em cima. As correntes do oceano se movem assim, com água fria e quente!"] }, at: "Mensagem na garrafa", m: "papel, lápis, uma garrafinha limpa (só para enfeitar, não jogue no mar!)", p: ["Escreva uma mensagem para uma criança de outro país, contando quem você é e do que gosta.", "Enrole o papel e coloque na garrafinha como enfeite do quarto.", "Escreva no diário: “Mergulho 20: o mar tem estradas invisíveis”."], q: "Se você mandasse uma mensagem numa garrafa, para onde gostaria que ela chegasse?" },
en: { h: "At the beach, Nina found a bottle with a note inside, written in another language! “How did it get here?” she asked, delighted. “The sea has invisible roads,” Grandpa explained. “They're ocean currents, which carry water, animals and even bottles around the world.”", t: "Ocean currents", f: "The ocean doesn't stay still: it has currents, like giant rivers inside the sea. Some are warm, others are cold. They're driven by wind, Earth's rotation and differences in water temperature and saltiness. Currents spread heat around the planet and help shape the climate.", x: "In 1992, a ship lost thousands of rubber ducks and bath toys in the Pacific Ocean. For many years, they kept turning up on beaches all over the world, and scientists used them to study currents!", s: ["A warm current from the equator flows south along the coast of Brazil.", "Turtles, whales and fish larvae use currents like conveyor belts to travel.", "Trash thrown into the sea is also carried by currents and piles up in certain parts of the ocean."], ex: { t: "Warm current, cold current", m: "a clear container of warm water, ice cubes made with water and blue food coloring", p: ["Fill the container with warm tap water and wait until the water is still.", "Gently place a blue ice cube in one corner.", "Watch: the cold blue water sinks to the bottom and spreads out, while the warm water stays on top. Ocean currents move like this, with cold and warm water!"] }, at: "Message in a bottle", m: "paper, pencil, a small clean bottle (just for decoration, don't throw it in the sea!)", p: ["Write a message to a kid in another country, telling them who you are and what you like.", "Roll up the paper and put it in the bottle as a decoration for your room.", "Write in your log: “Dive 20: the sea has invisible roads.”"], q: "If you sent a message in a bottle, where would you like it to end up?" },
es: { h: "En la playa, Nina encontró una botella con una nota adentro, ¡escrita en otro idioma! “¿Cómo llegó hasta aquí?”, preguntó, encantada. “El mar tiene caminos invisibles”, explicó el abuelo. “Son las corrientes marinas, que llevan agua, animales y hasta botellas por el mundo.”", t: "Las corrientes marinas", f: "El océano no está quieto: tiene corrientes, como ríos gigantes dentro del mar. Algunas son cálidas y otras frías. Las mueven el viento, la rotación de la Tierra y las diferencias de temperatura y de sal del agua. Las corrientes reparten el calor por el planeta y ayudan a formar el clima.", x: "¡En 1992, un barco perdió en el océano Pacífico miles de patitos y juguetes de goma! Durante muchos años fueron apareciendo en playas de todo el mundo, y los científicos los usaron para estudiar las corrientes.", s: ["Por la costa de Chile y Perú pasa una corriente fría que trae muchos nutrientes y muchos peces.", "Las tortugas, las ballenas y las larvas de peces usan las corrientes como cintas transportadoras para viajar.", "La basura tirada al mar también es llevada por las corrientes y se acumula en ciertos lugares del océano."], ex: { t: "Corriente cálida, corriente fría", m: "un recipiente transparente con agua tibia, cubitos de hielo hechos con agua y colorante azul", p: ["Llena el recipiente con agua tibia de la canilla y espera a que el agua quede quieta.", "Pon con cuidado un cubito de hielo azul en un rincón.", "Observa: el agua azul y fría baja al fondo y se esparce, mientras la tibia queda arriba. ¡Las corrientes del océano se mueven así, con agua fría y caliente!"] }, at: "Mensaje en una botella", m: "papel, lápiz, una botellita limpia (¡solo para decorar, no la tires al mar!)", p: ["Escribe un mensaje para un niño de otro país, contándole quién eres y qué te gusta.", "Enrolla el papel y ponlo en la botellita como adorno para tu cuarto.", "Escribe en el diario: “Inmersión 20: el mar tiene caminos invisibles”."], q: "Si mandaras un mensaje en una botella, ¿adónde te gustaría que llegara?" } },
];
